export const getSubmitPracticeAttemptUrl = () => {




  return `/api/practice/attempts`
}

/**
 * Evaluates a learner's answer and returns coaching feedback
 * @summary Submit a practice attempt
 */
export const submitPracticeAttempt = async (practiceAttemptInput: PracticeAttemptInput, options?: Parameters<typeof customFetch>[1]): Promise<PracticeAttempt> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<PracticeAttempt>(getSubmitPracticeAttemptUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(practiceAttemptInput)
  }
);}





export const getSubmitPracticeAttemptMutationKey = () => ['submitPracticeAttempt'] as const;

export const getSubmitPracticeAttemptMutationOptions = <TError = ErrorType<ErrorResponse | CoachingLimitReached>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof submitPracticeAttempt>>, TError,SubmitPracticeAttemptMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof submitPracticeAttempt>>, TError,SubmitPracticeAttemptMutationVariables, TContext> => {

const mutationKey = getSubmitPracticeAttemptMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof submitPracticeAttempt>>, SubmitPracticeAttemptMutationVariables> = (props) => {
          const {data} = props ?? {};

          return  submitPracticeAttempt(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type SubmitPracticeAttemptMutationResult = NonNullable<Awaited<ReturnType<typeof submitPracticeAttempt>>>
    export type SubmitPracticeAttemptMutationBody = BodyType<PracticeAttemptInput>
    export type SubmitPracticeAttemptMutationError = ErrorType<ErrorResponse | CoachingLimitReached>
    export type SubmitPracticeAttemptMutationVariables = {data: BodyType<PracticeAttemptInput>}

    /**
 * @summary Submit a practice attempt
 */
export const useSubmitPracticeAttempt = <TError = ErrorType<ErrorResponse | CoachingLimitReached>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof submitPracticeAttempt>>, TError,SubmitPracticeAttemptMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof submitPracticeAttempt>>,
        TError,
        SubmitPracticeAttemptMutationVariables,
        TContext
      > => {
      return useMutation(getSubmitPracticeAttemptMutationOptions(options));
    }

